class FitnessCenter {
  + name : string
  + address : string
}

class Room {
  + number : int
  + capacity : int
}

abstract class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Member {
}

class Trainer {
  + diploma : string
}

class Prospect {
}

class Intern {
}

abstract class Session {
  + date : date
  + startHour : time
}

class IndividualSession {
}

class GroupSession {
  + type : string
}

FitnessCenter "1" *-- "1..*" Room
Room "1" -- "0..*" Session

Person "1" -- "0..*" Member : is
Person "1" -- "0..*" Trainer : is
Person "1" -- "0..*" Prospect : is
Person "1" -- "0..*" Intern : is

Trainer "1" -- "0..*" GroupSession : supervises
Member "0..*" -- "0..*" Session : participates

GroupSession --|> Session
IndividualSession --|> Session

@enduml

